const c14HalfLife=5730;
const c14Remaining=age=>100*Math.pow(0.5,age/c14HalfLife);
const c14Age=percent=>percent>0&&percent<=100?-c14HalfLife*Math.log2(percent/100):null;
const c14Samples={wood:['🪵 Tre / trekull','Vi daterer når karbonet ble bundet i treets vev. Gammelt tre kan derfor være eldre enn bålet det ble brukt i.'],bone:['🦴 Bein (kollagen)','Kollagen er organisk materiale i bein. Karbonet kommer fra maten dyret eller mennesket spiste.'],linen:['🌿 Lintekstil','Lin kommer fra planter. Dateringen gjelder plantematerialet, ikke nødvendigvis tidspunktet tekstilet ble vevd.']};
function carbonDatingMarkup(){return `<section class="c14-lab" aria-label="C-14-simulator"><div class="c14-heading"><p class="eyebrow">KARBON SOM KLOKKE</p><h2>Hvor gammelt er materialet?</h2><p>Utforsk hvordan mengden karbon-14 avtar etter at et levende materiale slutter å utveksle karbon med omgivelsene.</p></div><div class="c14-grid"><div class="c14-controls"><label>Organisk materiale<select data-c14="sample">${Object.entries(c14Samples).map(([key,v])=>`<option value="${key}">${v[0]}</option>`).join('')}</select></label><p class="note" data-c14="sampleNote"></p><label>Alder i modellen (år)<input data-c14="age" type="number" min="0" max="50000" step="any" value="5730"></label><input data-c14="slider" type="range" aria-label="Endre modellalder" min="0" max="50000" step="10" value="5730"><div class="c14-range-labels"><span>0 år</span><span>50 000 år</span></div><label>C-14 igjen (% av forventet startmengde)<input data-c14="percent" type="number" min="0" max="100" step="any" value="50"></label><p class="note">100 % betyr startmengden C-14 for denne mengden karbon. Det betyr ikke at materialet består av 100 % C-14.</p><p data-c14="error" class="c14-error" role="status"></p><div class="c14-presets" aria-label="Prøv halveringstider">${[0,1,2,3].map(i=>`<button data-c14-years="${i*5730}">${i===0?'Nylig levende':i+' halveringstid'+(i>1?'er':'')}</button>`).join('')}</div></div><div class="c14-results"><div class="c14-stats" aria-live="polite"><div><span>Modellalder</span><strong data-c14="ageResult"></strong></div><div><span>C-14 igjen</span><strong data-c14="percentResult"></strong></div></div><div class="c14-bar" role="img" aria-label="Andel C-14 som er igjen"><span data-c14="bar"></span></div><p class="note">Grønt = C-14 igjen · lyst = C-14 som har henfalt</p><svg data-c14="chart" viewBox="0 0 560 270" role="img" aria-label="Henfallskurve for karbon-14"><g stroke="#d5dfd4" fill="none"><path d="M50 20V225H535"/><path d="M50 122.5H535M50 20H535" stroke-dasharray="4 5"/></g><g fill="#526459" font-size="12"><text x="8" y="24">100 %</text><text x="15" y="127">50 %</text><text x="24" y="229">0 %</text><text x="50" y="249">0</text><text x="268" y="249">25 000</text><text x="475" y="249">50 000 år</text></g><path data-c14="curve" fill="none" stroke="#307451" stroke-width="3"/><path data-c14="guide" fill="none" stroke="#aa7939" stroke-dasharray="5 4"/><circle data-c14="dot" r="7" fill="#aa7939" stroke="white" stroke-width="2"/></svg><p data-c14="resultNote" class="c14-insight"></p><p class="note">Kurven viser gjennomsnittlig henfall i en stor prøve. Ett enkelt atoms henfallstidspunkt kan ikke forutsies. Materialvalget endrer ikke halveringstiden.</p></div></div><div class="c14-explanation"><section><h3>1. Mens organismen lever</h3><p>Planter tar opp karbon gjennom fotosyntesen. Dyr får karbon gjennom maten. En svært liten del er radioaktivt C-14; det meste er de stabile isotopene C-12 og C-13.</p></section><section><h3>2. Etter at karbonutvekslingen stopper</h3><p>C-14 henfaller til nitrogen-14. Etter omtrent <b>5 730 år</b> er halvparten igjen. Etter 11 460 år er en fjerdedel igjen. C-12 og C-13 henfaller ikke på denne måten.</p></section><section><h3>3. Fra måling til alder</h3><p>Forskere måler C-14 i forhold til stabilt karbon og sammenligner med forventet startnivå. Metoden brukes på for eksempel tre, frø, tekstiler og beinkollagen, vanligvis opptil rundt 50 000 år.</p></section></div><details><summary>Hvorfor er dette en forenklet modell?</summary><p>Her antar vi kjent startnivå og en lukket prøve uten forurensning. Startnivået i atmosfæren har variert. Virkelige dateringer kalibreres derfor med blant annet årringer, og oppgis med usikkerhet. Karbon fra havet eller gammelt karbon kan også kreve korreksjoner.</p><p>Dette er tid siden karbonutvekslingen stoppet, ikke et bestemt kalenderår. Vi bruker den fysiske halveringstiden 5 730 år. Konvensjonelle radiokarbondateringer bruker historisk 5 568 år før kalibrering. Kalkulatoren gir derfor ikke en ferdig kalibrert arkeologisk datering.</p><p>Modell: andel igjen = ½<sup>alder / 5730</sup>. Alder = −5730 × log₂(andel igjen). Null målbart C-14 gir ingen bestemt alder i denne modellen. Dinosaurfossiler er altfor gamle for C-14-datering.</p><p>Kilder: <a href="https://www.radiocarbon.org.uk/dating.html" target="_blank" rel="noreferrer">Oxford: Radiocarbon dating ↗</a> · <a href="https://www.radiocarbon.org.uk/calibration.html" target="_blank" rel="noreferrer">Oxford: Kalibrering ↗</a></p></details></section>`;}
function initCarbonDating(host){host.querySelectorAll('.c14-lab').forEach(lab=>{
 const q=name=>lab.querySelector(`[data-c14="${name}"]`),fmt=(n,d=0)=>n.toLocaleString('nb-NO',{maximumFractionDigits:d});
 const minPercent=c14Remaining(50000);
 q('curve').setAttribute('d',Array.from({length:201},(_,i)=>`${i?'L':'M'}${50+i/200*485},${225-c14Remaining(i*250)/100*205}`).join(' '));
 function update(age,origin){const pc=c14Remaining(age);q('error').textContent='';if(origin!=='age')q('age').value=Number(age.toFixed(1));if(origin!=='percent')q('percent').value=Number(pc.toFixed(4));q('slider').value=age;q('ageResult').textContent=fmt(age)+' år';q('percentResult').textContent=fmt(pc,3)+' %';q('bar').style.width=pc+'%';q('bar').parentElement.setAttribute('aria-label',fmt(pc,3)+' prosent C-14 igjen');const x=50+age/50000*485,y=225-pc/100*205;q('dot').setAttribute('cx',x);q('dot').setAttribute('cy',y);q('guide').setAttribute('d',`M50 ${y}H${x}V225`);q('resultNote').textContent=`Etter ${fmt(age)} år er omtrent ${fmt(pc,3)} % av startmengden C-14 igjen. Det tilsvarer ${fmt(age/5730,2)} ${age===5730?'halveringstid':'halveringstider'}.`;}
 q('age').oninput=()=>{const v=q('age').valueAsNumber;if(!Number.isFinite(v)||v<0||v>50000){q('error').textContent='Skriv en alder mellom 0 og 50 000 år. Resultatet viser siste gyldige verdi.';return}update(v,'age')};
 q('percent').oninput=()=>{const v=q('percent').valueAsNumber;if(!Number.isFinite(v)||v<minPercent||v>100){q('error').textContent=v===0?'0 % gir ingen bestemt alder. Prøven kan være utenfor måleområdet. Resultatet viser siste gyldige verdi.':`Bruk mellom ${fmt(minPercent,4)} % og 100 %. Lavere andeler tilsvarer mer enn 50 000 år. Resultatet viser siste gyldige verdi.`;return}update(c14Age(v),'percent')};
 q('slider').oninput=()=>update(Number(q('slider').value));lab.querySelectorAll('[data-c14-years]').forEach(b=>b.onclick=()=>update(Number(b.dataset.c14Years)));
 q('sample').onchange=()=>q('sampleNote').textContent=c14Samples[q('sample').value][1];q('sample').onchange();update(5730);
 });}
